import { EMAIL_PROVISORIO, type Conteudo } from './schema.ts';

/** Path of the share image generated by src/pages/og.png.ts. */
export const CAMINHO_OG = '/og.png';
export const LARGURA_OG = 1200;
export const ALTURA_OG = 630;

/** Absolute URL of a path on the site, or undefined when there is no site.url. */
export function urlAbsoluta(site: string | undefined, caminho: string): string | undefined {
  return site ? new URL(caminho, site).href : undefined;
}

/** Open Graph locale from a BCP 47 tag: "pt-BR" -> "pt_BR". */
export function localeOg(idioma: string): string {
  const [lingua = '', regiao] = idioma.split(/[-_]/);
  return regiao ? `${lingua.toLowerCase()}_${regiao.toUpperCase()}` : lingua.toLowerCase();
}

/** Short line for the share image and its alt text: the nickname, or the site title. */
export function chamadaPrincipal(conteudo: Conteudo): string {
  const hero = conteudo.secoes.find((secao) => secao.tipo === 'hero' && secao.ativo);
  return hero?.tipo === 'hero' ? hero.apelido : conteudo.site.titulo;
}

type Objeto = Record<string, unknown>;

/**
 * schema.org JSON-LD for the home page: the artist (MusicGroup, which Google uses for solo
 * artists too), the person behind it and the featured releases. A placeholder e-mail is left out.
 */
export function gerarJsonLd(conteudo: Conteudo): Objeto {
  const { site, artista, contato } = conteudo;
  const url = urlAbsoluta(site.url, '/');
  const endereco = {
    '@type': 'PostalAddress',
    addressLocality: artista.cidade,
    addressRegion: artista.uf,
    addressCountry: 'BR',
  };
  const pessoa: Objeto = {
    '@type': 'Person',
    '@id': url && `${url}#pessoa`,
    name: artista.nome,
    alternateName: artista.nome_artistico,
    birthDate: artista.ano_nascimento?.toString(),
    address: endereco,
  };
  // Audio releases only; the short videos are promos, not recordings.
  const faixas = conteudo.secoes
    .flatMap((secao) => (secao.tipo === 'musica' && secao.ativo ? secao.itens : []))
    .filter((item) => item.plataforma === 'soundcloud')
    .map((item) => ({ '@type': 'MusicRecording', name: item.titulo, url: item.url, datePublished: item.data }));
  const grupo: Objeto = {
    '@type': 'MusicGroup',
    '@id': url && `${url}#artista`,
    name: artista.nome_artistico,
    alternateName: artista.apelido,
    description: site.descricao,
    url,
    image: urlAbsoluta(site.url, CAMINHO_OG),
    genre: artista.generos.length > 0 ? artista.generos : undefined,
    foundingLocation: { '@type': 'Place', address: endereco },
    member: url ? { '@id': `${url}#pessoa` } : { '@type': 'Person', name: artista.nome },
    sameAs: artista.perfis.length > 0 ? artista.perfis : undefined,
    track: faixas.length > 0 ? faixas : undefined,
  };
  if (!EMAIL_PROVISORIO.test(contato.email)) grupo.email = contato.email;
  return { '@context': 'https://schema.org', '@graph': [grupo, pessoa] };
}

/**
 * JSON for an inline <script type="application/ld+json">: `<`, `>` and `&` are escaped
 * as \u00XX so the content can never close the script tag (JSON.stringify drops undefined).
 */
export function serializarJsonLd(dados: unknown): string {
  return JSON.stringify(dados)
    .replaceAll('<', '\\u003c')
    .replaceAll('>', '\\u003e')
    .replaceAll('&', '\\u0026');
}

/**
 * robots.txt: crawling stays allowed even while the site is "em construção", because
 * crawlers only see the `noindex` meta of a page they are allowed to fetch.
 */
export function robotsTxt(site: string | undefined): string {
  const linhas = ['User-agent: *', 'Allow: /'];
  const sitemap = urlAbsoluta(site, '/sitemap-index.xml');
  if (sitemap) linhas.push('', `Sitemap: ${sitemap}`);
  return `${linhas.join('\n')}\n`;
}
